{
  "world_id": "wld_blackwood_asylum",
  "name": "Blackwood Asylum",
  "description": "A remote asylum cut off from the nearest town by a flooded moor road, run under strict clinical protocol. A newly arrived psychiatrist finds that every patient, regardless of age, history or diagnosis, reports the same impossible dream: a staircase that descends upward into a ward that does not exist in the building's plans. The tone is clinical and detached, told through charts, dosage logs and observation notes. The horror comes from data that does not add up. The asylum is lit only by electric lamps and shuttered windows, and the staff keep a rigid schedule so that no one has to look at the sky. The dream is spreading, and it appears to be rewriting the building itself.",
  "locations": [
    {
      "id": "loc_blackwood_asylum",
      "name": "Blackwood Asylum",
      "description": "A single sprawling brick asylum on a drowned moor, made up of an admissions hall, a long male and female ward, a hydrotherapy wing, a records vault and a sealed east stair. Every window is bricked or shuttered. The building has one more floor than its blueprints show, and that floor can be reached only in the dream."
    }
  ],
  "factions": [
    {
      "id": "fac_clinical_staff",
      "name": "The Observation Staff",
      "description": "Doctors, orderlies and nurses who enforce a rigid chart-everything protocol. They believe the shared dream is a contagion of suggestion and suppress any talk of it. Privately, several of them have started having the dream themselves.",
      "location_ids": ["loc_blackwood_asylum"]
    },
    {
      "id": "fac_dreamers",
      "name": "The Stair Congregation",
      "description": "A group of patients who compare dream notes in whispers and map the impossible ward room by room. They want to descend the staircase fully, and some have begun to leave the waking ward in small ways, such as missing reflections and sleepwalking in perfect unison.",
      "location_ids": ["loc_blackwood_asylum"]
    }
  ],
  "rules": [
    {
      "id": "rul_shared_dream",
      "statement": "Every resident of the asylum who sleeps within its walls dreams the same staircase, and details one dreamer adds appear in the dreams of all others within one night.",
      "category": "metaphysics"
    },
    {
      "id": "rul_extra_floor",
      "statement": "The building has one more floor than any measurement can confirm; the extra floor exists only for those who have dreamed the stair at least seven nights running.",
      "category": "physics"
    },
    {
      "id": "rul_no_sky",
      "statement": "No resident may look at the open sky; the staff cover windows and escort patients through enclosed passages, and anyone who sees the sky is said to lose the ability to wake properly.",
      "category": "social"
    },
    {
      "id": "rul_charting",
      "statement": "All events must be charted in the shared ledger; entries are never erased, and handwriting in the ledger sometimes changes to a hand no staff member recognizes.",
      "category": "other"
    },
    {
      "id": "rul_sedation",
      "statement": "Sedatives do not stop the dream; they only prevent the dreamer from remembering it, and the stair advances further on sedated nights.",
      "category": "technology"
    }
  ],
  "history": [
    {
      "id": "evt_founding",
      "name": "Founding of the Asylum",
      "description": "The asylum was built by a reformist physician to house the incurable, using the moor's black oak. The architect's plans were filed with only four floors, though the finished building was recorded by contractors as having five.",
      "era": "Victorian reform era",
      "location_ids": ["loc_blackwood_asylum"]
    },
    {
      "id": "evt_first_sleepers",
      "name": "The Night of Matching Dreams",
      "description": "Forty patients woke at the same minute describing the same stair. The attending physician recorded it as mass hysteria and sedated the ward. By morning the east stair had been walled off from the inside.",
      "era": "Interwar years",
      "location_ids": ["loc_blackwood_asylum"]
    },
    {
      "id": "evt_psychiatrist_arrives",
      "name": "Arrival of the New Psychiatrist",
      "description": "A psychiatrist arrives to evaluate the asylum's treatment outcomes and begins finding impossible consistencies in the charts. Their own sleep begins to change in the first week.",
      "era": "Present",
      "location_ids": ["loc_blackwood_asylum"]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_chart_vs_stair",
      "name": "Protocol Against the Stair",
      "description": "The Observation Staff try to suppress, sedate and chart away the dream, while the Stair Congregation tries to complete the descent. The psychiatrist must decide whether the dream is a disease to be cured or a place that is really there, and whether either side can be trusted.",
      "faction_ids": ["fac_clinical_staff", "fac_dreamers"]
    }
  ]
}

