response.output:
{
  "world_id": "wld_tidewrit_archipelago",
  "name": "The Tidewrit Archipelago",
  "description": "A chain of storm-bitten islands where two maritime powers fight a long, disciplined war under sail. It is a historical-inspired setting with a Napoleonic feel, and it has no gunpowder. Battles are decided by the ram, the ballista, the fire-pot and the discipline of a well-drilled fleet. Orders pass between ships by signal lantern and by tide-ink, a dark ink that stays legible only while it is wetted by salt water. The tone is stoic. Duty is spoken of plainly, grief is carried without display, and honour is measured by what a person endures quietly. Into this war steps Captain Aurelio Vane of the Meridian Navy. During a parley he learns that the admiral commanding the enemy fleet is his estranged brother, Corvin Vane. Both men are bound by oaths, by the Corsair's Code that governs privateers and their prizes, and by a family silence nearly twenty years old.",
  "locations": [
    {
      "id": "loc_port_meridian",
      "name": "Port Meridian",
      "description": "A walled harbour city of grey stone and tarred rope. It is the home anchorage of the Meridian fleet, and its sea-wall is ringed with ballista towers."
    },
    {
      "id": "loc_saltglass_reach",
      "name": "Saltglass Reach",
      "description": "A shallow strait where evaporated brine has crusted into glassy flats. Ships can cross only at high tide, so battles here are timed by the moon."
    },
    {
      "id": "loc_isle_of_ledgers",
      "name": "Isle of Ledgers",
      "description": "A neutral rock where the Corsair's Code is kept. Clerks inscribe every letter of marque in tide-ink and settle disputes over prizes."
    },
    {
      "id": "loc_dravenmoor_citadel",
      "name": "Dravenmoor Citadel",
      "description": "The cliff fortress and flagship harbour of the Dravan Dominion. Its admiral's lantern-tower can be seen for thirty miles."
    }
  ],
  "factions": [
    {
      "id": "fac_meridian_navy",
      "name": "Meridian Navy",
      "description": "The regular sea service of the Meridian Republic. It is rigid, proud and ruled by written signal doctrine, and it values restraint above brilliance.",
      "location_ids": ["loc_port_meridian", "loc_saltglass_reach"]
    },
    {
      "id": "fac_dravan_armada",
      "name": "Dravan Armada",
      "description": "The imperial fleet of the Dravan Dominion, led by Admiral Corvin Vane. It is a defector-built force that favours bold flanking manoeuvres and lantern-coded orders.",
      "location_ids": ["loc_dravenmoor_citadel", "loc_saltglass_reach"]
    },
    {
      "id": "fac_ledger_wardens",
      "name": "Ledger Wardens",
      "description": "Neutral clerks and arbiters who guard the Corsair's Code. They sell certified tide-ink and punish anyone who forges a letter of marque.",
      "location_ids": ["loc_isle_of_ledgers"]
    }
  ],
  "rules": [
    {
      "id": "rul_no_gunpowder_weapons",
      "statement": "No explosive propellant exists; naval war is fought with rams, ballistae, boarding and sealed pots of burning pitch.",
      "category": "technology"
    },
    {
      "id": "rul_tide_ink_fades",
      "statement": "Tide-ink orders remain legible only while kept damp with salt water, so every sealed command expires unless carried to sea quickly.",
      "category": "physics"
    },
    {
      "id": "rul_lantern_parley",
      "statement": "A flagship that has hung the white parley lantern may not be attacked until the lantern is lowered, and breaking this custom brands a commander oath-breaker in every port.",
      "category": "social"
    },
    {
      "id": "rul_marque_binding",
      "statement": "A letter of marque is binding only if inscribed on the Isle of Ledgers; prizes taken under a forged letter are forfeit to the Wardens.",
      "category": "social"
    },
    {
      "id": "rul_kin_cannot_command",
      "statement": "By the Corsair's Code, an officer who learns a blood relative leads the opposing fleet must declare it within three tides or be struck from the rolls.",
      "category": "other"
    }
  ],
  "history": [
    {
      "id": "evt_founding_of_code",
      "name": "Writing of the Corsair's Code",
      "description": "Privateer captains and clerks met on the Isle of Ledgers to bind sea-raiding to written law after a decade of lawless prize wars.",
      "era": "Age of Open Seas",
      "location_ids": ["loc_isle_of_ledgers"]
    },
    {
      "id": "evt_vane_estrangement",
      "name": "The Vane Parting",
      "description": "After their father's disgrace, the young Corvin Vane left Port Meridian to serve the Dominion. Aurelio stayed and never answered his letters.",
      "era": "Age of Open Seas",
      "location_ids": ["loc_port_meridian", "loc_dravenmoor_citadel"]
    },
    {
      "id": "evt_glass_tide_battle",
      "name": "Battle of the Glass Tide",
      "description": "A Meridian fleet was trapped on the Saltglass flats by an early ebb and lost eleven hulls to Dravan rams, a defeat that made the war personal.",
      "era": "Age of Open Seas",
      "location_ids": ["loc_saltglass_reach"]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_brothers_of_the_fleet",
      "name": "Brother Against Brother",
      "description": "Aurelio must either declare his kinship and be removed, or hide it and fight an admiral who knows his tactics as well as he does. Each choice betrays an oath of either blood or duty.",
      "faction_ids": ["fac_meridian_navy", "fac_dravan_armada"]
    },
    {
      "id": "cnf_forged_marques",
      "name": "The Forged Marques",
      "description": "Someone is selling forged letters of marque to raiders on both sides. The Wardens suspect the war is being prolonged on purpose.",
      "faction_ids": ["fac_ledger_wardens", "fac_meridian_navy", "fac_dravan_armada"]
    }
  ]
}

